import { ColumnDef } from '@tanstack/react-table';
import { format, isValid, parseISO } from 'date-fns';
import { EntryExit } from '../../types/configs.types';

const formatEntryDate = (value: string | Date | null | undefined): string => {
    if (!value) return '--';
    const date = value instanceof Date ? value : parseISO(value);
    if (!isValid(date)) return '--';
    return format(date, 'yyyy-MM-dd');
};

export const columns: ColumnDef<EntryExit>[] = [
    {
        accessorKey: 'date',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    التاريخ
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {formatEntryDate(row.original.date)}
            </div>
        ),
    },
    {
        accessorKey: 'check_in',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    وقت الدخول
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.check_in}
                </div>
            );
        },
    },
    {
        accessorKey: 'check_out',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    وقت الخروج
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.check_out}
                </div>
            );
        },
    },
    {
        accessorKey: 'work_hours',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    ساعات العمل
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.work_hours}
                </div>
            );
        },
    },
    {
        accessorKey: 'break_time',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    وقت الراحة
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.break_time}
                </div>
            );
        },
    },

];
